import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,T as c,_ as l,b as u,i as d,k as f,l as p,n as m,o as h,r as g,t as _,u as v,v as y}from"./shared-CsAEn-Fy.js";import{t as b}from"./CodeEditor-BZlrvoTL.js";var x=e(),S=`Этап 4 · Блок 14 · Подготовка базы и новой границы хранения`;function C({module:e}){return(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{variant:`project`,chip:e??S,title:`68.1. Транзакция и откат`,intro:`После первой успешной ORM-записи разберём обратный путь: как отменить связанную работу после ошибки и сохранить Session пригодной для следующей операции.`}),(0,x.jsxs)(s,{number:`00`,title:`Вступление`,children:[(0,x.jsx)(o,{children:`В предыдущем шаге строка TaskRow прошла через add, flush и commit, а новая Session прочитала её из отдельной SQLite-базы. Такой сценарий объяснил успех, но оставил вопрос: что делать, если несколько связанных изменений начались, а одно из них нарушило ограничение таблицы?`}),(0,x.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`Мы уже умеем записать TaskRow через фабрику Session и проверить сохранённое состояние независимым чтением.`},{title:`Новый вопрос`,description:`Мы выясним, что остаётся после ошибки flush и как продолжить работу без частичного изменения.`},{title:`Результат`,description:`Мы проверим отмену, восстановление Session и закрытие ресурса на изолированной базе.`}]}),(0,x.jsx)(`p`,{children:`В этой главе мы постепенно готовим тот же Planner к SQLite, но рабочие API и CLI пока продолжают использовать JSON. Поэтому транзакцию изучим в отдельной тестовой базе, а не включим новую схему в приложение. Сначала отделим Session от транзакции, затем проследим границы flush, commit, rollback и close. После этого в следующем занятии сможем безопасно читать ORM-строки и преобразовывать их в знакомую предметную Task.`})]}),(0,x.jsxs)(s,{number:`01`,title:`Session и транзакция отвечают за разное`,children:[(0,x.jsx)(o,{children:`Session организует работу Python-объектов с базой и управляет соединением. Транзакция задаёт границу изменений, которые база должна подтвердить вместе или отменить.`}),(0,x.jsx)(`p`,{children:`В предыдущем занятии фабрика sessionmaker создавала короткоживущую Session для выбранного Engine. Внутри Session мы добавляли ORM-строку, отправляли SQL и фиксировали успешный результат. Но сама Session не является одной транзакцией навсегда: пока она открыта, в ней могут завершиться несколько последовательных транзакций. На практике мы всё равно ограничиваем её одной понятной операцией, чтобы не удерживать ресурсы дольше нужного.`}),(0,x.jsx)(`p`,{children:`Представим Session как рабочее место, которое мы временно заняли для одной задачи: рядом лежат ORM-объекты, а при первом обращении к базе подключается нужный ресурс. Транзакция похожа на отдельную партию связанных изменений на этом месте. Когда партия принята, она подтверждена; когда в ней обнаружена ошибка, её можно целиком вернуть к исходному состоянию. Аналогия помогает увидеть разные границы, но само рабочее место не хранит запись вместо базы.`}),(0,x.jsx)(t,{rows:[[(0,x.jsx)(`code`,{children:`Session`}),`Рабочее состояние ORM и полученные ресурсы подключения.`],[(0,x.jsx)(`code`,{children:`flush()`}),`Отправляет накопленные изменения SQL-командами внутри текущей транзакции.`],[(0,x.jsx)(`code`,{children:`commit()`}),`Сначала при необходимости выполняет flush, затем подтверждает транзакцию.`],[(0,x.jsx)(`code`,{children:`rollback()`}),`Отменяет текущую транзакцию и возвращает Session в рабочее состояние.`],[(0,x.jsx)(`code`,{children:`close()`}),`Освобождает ресурсы Session; само по себе не подтверждает изменения.`]]}),(0,x.jsx)(`p`,{children:`Вторая аналогия: транзакция похожа на один конверт с несколькими взаимосвязанными документами. Мы отправляем весь конверт только после проверки комплекта; если один лист неверен, отзываем весь набор. Это объясняет атомарность, то есть целостный результат сценария. Граница аналогии в том, что внешний эффект, например уже отправленное письмо, база отменить не может. Здесь рассматриваем только SQL-изменения в одной SQLite-транзакции.`}),(0,x.jsx)(r,{tone:`info`,children:`Session отвечает за рабочий ресурс, транзакция за подтверждение изменений. Эти понятия часто живут рядом в коде, но ни одно не заменяет другое.`})]}),(0,x.jsxs)(s,{number:`02`,title:`flush отправляет SQL, commit подтверждает результат`,children:[(0,x.jsx)(o,{children:`Сначала посмотрим, что мы можем наблюдать до commit. Полученный id полезен, но ещё не доказывает, что запись переживёт завершение текущей транзакции.`}),(0,x.jsx)(`p`,{children:`Вызов add помещает TaskRow в рабочую область Session. Затем flush отправляет INSERT в базу, и SQLite может выдать первичный ключ. Но отправка SQL проходит внутри ещё открытой транзакции. Пока мы не вызвали commit или не вышли успешно из транзакционного контекста, другой независимой Session не следует считать эту запись подтверждённой.`}),(0,x.jsx)(`p`,{children:`Commit выполняет ожидающий flush, если он ещё нужен, а затем завершает транзакцию. Refresh решает другую задачу: повторно загружает состояние ORM-объекта из базы в ту же Session. Он не подтверждает запись и не заменяет независимое чтение, которое мы использовали после успешной операции.`}),(0,x.jsx)(`p`,{children:`Проследим два значения после отправки SQL. Объект уже может содержать id, и Session показывает активную транзакцию. Оба наблюдения описывают промежуточное состояние, а не долговечный результат.`}),(0,x.jsx)(l,{code:`row = TaskRow(title="Кабель", priority=2, is_done=False, tags=[], title_normalized="кабель")
with session_factory() as session:
    session.add(row)
    session.flush()
    print(row.id is not None)
    print(session.in_transaction())`,output:`True
True`,hint:`Сравним id объекта и состояние транзакции сразу после flush.`}),(0,x.jsx)(`p`,{children:`В примере успешный flush дал объекту id, а транзакция осталась активной. Когда внешний блок Session завершится без commit, работа не превратится в сохранённую запись. Приёмка всегда спрашивает, был ли сделан commit или успешно завершился session.begin(), а не только то, вернулся ли flush.`}),(0,x.jsx)(u,{question:`Какой результат мы получим от refresh после flush, если commit ещё не было?`,options:[`Refresh подтверждает транзакцию и записывает все изменения навсегда.`,`Refresh перечитывает объект, но сам не подтверждает текущую транзакцию.`,`Refresh закрывает Session и освобождает соединение.`],correctIndex:1,explanation:`Refresh синхронизирует ORM-объект с базой в рамках текущей Session. Границу подтверждения задаёт commit, а ресурсы освобождает close.`})]}),(0,x.jsxs)(s,{number:`03`,title:`Транзакцию начинаем до первого SQL-обращения`,children:[(0,x.jsx)(o,{children:`SQLAlchemy умеет начинать транзакцию автоматически при первом обращении Session к базе. Это удобно в обычной работе, но важно учитывать, если мы задаём явную границу через begin().`}),(0,x.jsx)(`p`,{children:`Такое автоматическое начало называют autobegin. Например, get или select отправляет запрос и запускает транзакцию, даже если запрос только читает данные. Поэтому явный session.begin() ставится до первого чтения и до изменений. Если мы сначала сделали запрос, а затем пытаемся начать ещё одну верхнеуровневую транзакцию, SQLAlchemy сообщает, что транзакция уже действует.`}),(0,x.jsx)(`p`,{children:`Пошагово разберём ошибочный порядок. Сначала создаётся Session, затем get обращается к таблице. После этого begin() пытается открыть новую область поверх уже начатой. Ошибка относится к порядку операций, а не к самому объекту TaskRow.`}),(0,x.jsx)(y,{code:`with session_factory() as session:
    session.get(TaskRow, 1)
    session.begin()`,steps:[{line:0,note:`Мы открыли ресурсную Session. Транзакция ещё не обязана быть начата.`,vars:{session:`открыта`}},{line:1,note:`Мы запросили строку. Первое обращение к базе автоматически начинает транзакцию.`,vars:{transaction:`активна`}},{line:2,note:`Мы вызвали begin() поверх уже активной транзакции. SQLAlchemy отклонит такой порядок.`,vars:{result:`ошибка начала второй области`}}]}),(0,x.jsx)(`p`,{children:`Исправим порядок на свежей Session: сначала открываем транзакционную область, затем читаем или меняем данные. Успешный выход из внутреннего begin() выполняет commit, а исключение, вышедшее из блока, запускает rollback. Внешний контекст Session при этом закрывает ресурс отдельно.`}),(0,x.jsx)(b,{caption:`Явная транзакция начинается до чтения и изменений`,code:`with session_factory() as session:
    with session.begin():
        current = session.get(TaskRow, 1)
        session.add(next_row)`}),(0,x.jsx)(r,{children:`Не добавляем begin() после первого запроса только потому, что это начало следующего участка кода. Сначала решаем, где находится граница всей операции, затем открываем её на свежей Session.`})]}),(0,x.jsxs)(s,{number:`04`,title:`Одна транзакция удерживает связанные изменения вместе`,children:[(0,x.jsx)(o,{children:`Проверка ограничения превращает неудачу в наблюдаемое событие. Мы увидим, почему первый уже отправленный INSERT исчезает вместе со вторым, который нарушил правило таблицы.`}),(0,x.jsx)(`p`,{children:`В модели TaskRow из предыдущего шага база проверяет диапазон priority от 1 до 5. Создадим корректную строку, вызовем flush, затем добавим строку с priority вне диапазона и снова явно выполним flush. Явный вызов полезен в учебной проверке: мы точно знаем, на каком шаге SQLite сообщает об ошибке ограничения.`}),(0,x.jsx)(`p`,{children:`Представим две строки как часть одного конверта изменений. Первый INSERT уже отправлен SQL-командой, но ещё не подтверждён. Ошибка второго INSERT делает всю текущую транзакцию неуспешной. После rollback независимое чтение не должно находить ни первую, ни ошибочную строку. Одного сообщения об IntegrityError мало: мы проверяем состояние базы.`}),(0,x.jsx)(`p`,{children:`В SQLAlchemy неудачный flush автоматически откатывает базовую транзакцию базы, но Session переходит в состояние partial rollback и не готова продолжать запросы. Явный rollback() завершает внутреннее состояние Session и освобождает её для новой работы. Если исключение выходит наружу из блока session.begin(), менеджер транзакции сам вызывает rollback, после чего передаёт исключение дальше.`}),(0,x.jsx)(`p`,{children:`Схема показывает две развилки одного сценария. Читаем её сверху вниз: успешная последовательность заканчивается подтверждением, а исключение отменяет изменения. Close находится в отдельной ресурсной области и не является третьим способом подтверждения.`}),(0,x.jsxs)(_,{caption:`Что происходит с одной транзакцией`,orientation:`vertical`,children:[(0,x.jsxs)(h,{label:`После начала транзакции изменения либо подтверждаются вместе, либо отменяются целиком`,orientation:`vertical`,children:[(0,x.jsx)(p,{title:`Начало одной операции`,shape:`terminator`,children:(0,x.jsx)(`p`,{children:`Свежая Session и граница до первого SQL`})}),(0,x.jsx)(m,{label:`изменения и flush`}),(0,x.jsx)(p,{title:`Ограничение таблицы`,shape:`decision`,children:(0,x.jsx)(`p`,{children:`Все строки допустимы?`})}),(0,x.jsx)(m,{label:`выбираем исход`}),(0,x.jsxs)(d,{label:`Два исхода транзакции`,children:[(0,x.jsxs)(g,{label:`Успех`,children:[(0,x.jsx)(p,{title:`Commit`,children:(0,x.jsx)(`p`,{children:`Все изменения подтверждены вместе`})}),(0,x.jsx)(m,{label:`новая Session видит записи`}),(0,x.jsx)(p,{title:`Проверяем итог`,shape:`database`,children:(0,x.jsx)(`p`,{children:`Читаем состояние независимо`})})]}),(0,x.jsxs)(g,{label:`Исключение до commit`,children:[(0,x.jsx)(p,{title:`Rollback`,children:(0,x.jsx)(`p`,{children:`Связанные изменения отменены`})}),(0,x.jsx)(m,{label:`ошибка остаётся видимой`}),(0,x.jsx)(p,{title:`Session восстановлена`,children:(0,x.jsx)(`p`,{children:`Можно начать новую транзакцию`})})]})]})]}),(0,x.jsx)(v,{title:`Внешняя область Session`,children:`После сценария close освобождает ресурс. Он не подтверждает данные и не заменяет rollback для восстановления той же Session после сбоя flush.`})]}),(0,x.jsx)(u,{question:`После корректного первого flush и ошибки ограничения во втором flush какая проверка доказывает атомарность?`,options:[`У исходного Python-объекта остался сгенерированный id.`,`Новая Session не находит ни одну строку из отменённого сценария.`,`Текущая Session вернула объект после неудачного flush.`],correctIndex:1,explanation:`Id мог появиться до commit. Независимое чтение после rollback проверяет состояние базы и показывает, что частичный результат не сохранился.`})]}),(0,x.jsxs)(s,{number:`05`,title:`После ошибки той же Session нужен rollback`,children:[(0,x.jsx)(o,{children:`Теперь отделим восстановление Session от открытия независимой Session. Новая Session подходит для проверки результата, но она не очищает состояние объекта, который пережил неудачный flush.`}),(0,x.jsx)(`p`,{children:`Если ошибка flush перехвачена внутри теста или обработчика, на первый взгляд код может продолжить выполнение. Но Session помнит, что предыдущая транзакция завершилась сбоем. Попытка выполнить следующий select до rollback приводит к PendingRollbackError: SQLAlchemy блокирует новые действия, пока мы явно не закроем неудавшуюся транзакционную область.`}),(0,x.jsx)(`p`,{children:`Rollback отменяет текущую работу и возвращает Session в пригодное состояние. После этого она может начать новую транзакцию, сохранить корректную строку и сделать commit. Это не исправляет ошибочную строку и не повторяет старый сценарий автоматически. Мы отдельно открываем новую Session и проверяем, что первая часть не сохранилась, а последующая успешная операция присутствует.`}),(0,x.jsx)(n,{code:`try:
    session.flush()
except IntegrityError:
    print("Запись не прошла")
print(session.scalar(select(TaskRow.id)))`,question:`Почему запрос после сообщения об ошибке не является безопасным продолжением?`,options:[`Ошибка уже перехвачена, поэтому Session автоматически начинает чистую транзакцию.`,`После сбоя flush Session остаётся неактивной; перед новым SQL нужен rollback().`,`Любой select запрещён для ORM-строк после INSERT.`],correctIndex:1,explanation:`Перехват Python-исключения не восстанавливает транзакционное состояние SQLAlchemy. Для продолжения той же Session явно вызываем rollback(), а нужную ошибку не превращаем в ложный успех.`,fix:`try:
    session.flush()
except IntegrityError:
    session.rollback()
    raise`}),(0,x.jsx)(`p`,{children:`В рабочем коде ошибка должна оставаться частью понятного контракта: либо она выходит к уже существующему слою обработки, либо тест фиксирует её как ожидаемую. Само занятие не добавляет HTTP-обработчики ошибок и не меняет API. В проверке мы можем перехватить IntegrityError через pytest.raises, проверить, что Session пока не принимает новый запрос, затем выполнить rollback и продолжить.`}),(0,x.jsx)(c,{question:`Какой вариант подходит, если две строки являются одной неделимой операцией?`,left:{title:`Подтверждать каждую строку отдельно`,code:`session.add(first_row)
session.flush()
session.commit()
session.add(second_row)
session.flush()
session.commit()`,note:`Если вторая строка отклонена, первая уже подтверждена и общей отмены не получится.`},right:{title:`Держать строки в одной транзакции`,code:`with session.begin():
    session.add(first_row)
    session.flush()
    session.add(second_row)
    session.flush()`,note:`Успешный выход подтверждает общий результат, а исключение отменяет изменения в этой области.`},preferred:`right`,explanation:`Мы выбираем границу по смыслу операции. Если строки связаны одним результатом, между ними нет отдельного commit; исключение выходит из begin() и запускает общий rollback.`})]}),(0,x.jsxs)(s,{number:`06`,title:`Ресурсная область закрывает Session, а не решает за нас commit`,children:[(0,x.jsx)(o,{children:`Внешний with Session управляет временем жизни ресурса, внутренний with session.begin() завершает транзакцию. Разделим эти блоки, чтобы успешный выход и ошибка имели предсказуемый результат.`}),(0,x.jsx)(`p`,{children:`Когда мы используем только with SessionFactory() as session, выход из блока закрывает Session и освобождает соединение. Если commit не было, незавершённая транзакция не становится сохранённой записью; соединение возвращается в пул после отката его транзакции. Но закрытие не является способом продолжить ту же Session после ошибки flush. Для этого требуется явный rollback до следующего SQL.`}),(0,x.jsx)(`p`,{children:`Если мы вкладываем with session.begin() внутрь области Session, обязанности видны прямо в коде. При нормальном выходе транзакционный блок фиксирует изменения. При исключении он отменяет их и повторно поднимает ошибку. Затем внешний блок освобождает Session. Для нового сценария создаётся следующая Session из той же фабрики.`}),(0,x.jsx)(`p`,{children:`Можно представить Session как временный стол в мастерской, а транзакцию как работу над одной деталью. Освободить стол важно после успеха и после неудачи, но уборка стола не делает незаконченный предмет готовым. Такая аналогия помогает не смешивать срок жизни ресурса с результатом операции; конкретное решение в коде всё равно задают контексты SQLAlchemy.`}),(0,x.jsx)(`p`,{children:`Проверим два близких фрагмента. В первом мы только ограничили ресурсный контекст. Во втором дополнительно указали транзакционную границу. Если цель состоит в сохранении новой строки, второй вариант выражает требование явно.`}),(0,x.jsx)(c,{question:`Какой фрагмент явно фиксирует успешное изменение и отменяет его при исключении?`,left:{title:`Только жизненный цикл Session`,code:`with session_factory() as session:
    session.add(row)`,note:`Контекст закроет ресурс, но код не попросил подтвердить транзакцию.`},right:{title:`Session и отдельная транзакция`,code:`with session_factory() as session:
    with session.begin():
        session.add(row)`,note:`Внутренний контекст подтверждает успех или отменяет изменения при исключении.`},preferred:`right`,explanation:`Внешний контекст ограничивает Session, а внутренний задаёт commit или rollback. Мы не поручаем close работу commit.`}),(0,x.jsx)(r,{tone:`info`,children:`В обычной конфигурации close освобождает ресурсы Session; он не превращает объект в навсегда запрещённый к использованию. В наших операциях проще и яснее открыть новую Session из фабрики.`})]}),(0,x.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(o,{children:`Общий результат практики: четыре проверки показывают отмену, отсутствие частичной записи, восстановление Session и освобождение ресурса на настоящей временной SQLite-базе.`}),(0,x.jsx)(r,{children:`В этой практике мы создадим отдельную модульную pytest-фикстуру isolated_database в tests/test_dbase_transactions.py. Она принимает tmp_path, создаёт временный файл transactions.sqlite3, подготавливает схему и возвращает пару (engine, session_factory); engine освобождается в finally. В каждом тесте принимаем isolated_database и распаковываем нужные значения. Фикстура не находится в conftest.py и не предполагается готовой после занятия 68. Рабочий JSON, API и CLI не используются как тестовая база.`}),(0,x.jsx)(f,{variant:`connected`,items:[{title:`Отменить незавершённую запись`,description:`Мы отправим изменение через flush, вызовем rollback и подтвердим новой Session, что строки нет.`},{title:`Проверить связанную транзакцию`,description:`Мы вызовем ограничение на второй строке и прочитаем, что первая не осталась частично сохранённой.`},{title:`Восстановить ту же Session`,description:`Мы увидим отказ запроса без rollback, затем продолжим новую операцию после явного восстановления.`},{title:`Завершить ресурсную область`,description:`Мы проверим выход при исключении и отдельно подтвердим итог в независимой Session.`}]}),(0,x.jsx)(`p`,{children:`Каждая проверка продолжает проектную работу из занятия 68, использует ограничение priority из схемы и опирается на уже знакомые Python-исключения и pytest. Мы не создаём второй Planner, SQL-репозиторий, HTTP-обработчик или универсальный Unit of Work. После практики остаётся понятный результат: никакой ложной успешной записи, одна явная граница отмены и безопасный ресурсный путь для чтения в следующем шаге.`})]})]})}export{C as Lesson68_1};